  clientSecret: attribute('client_secret', 'A confidential client credential used by the broker, not by the native app.', 'Provisioned for the broker client in Realm B and configured securely in A.', 'Authenticates the A-to-B token request. This example uses HTTP Basic client authentication.', 'broker-only secret; never shown to the browser', 'RFC 6749 §2.3.1', URLS.oauth),
  redirectApp: attribute('redirect_uri', 'The local address where the desktop app receives the browser callback.', 'The app binds a loopback listener; the allowed redirect is registered in A.', 'Lets the browser deliver the authorization code to the app on this computer.', EXAMPLE.appCallback, 'RFC 8252 §7.3', URLS.native),
  redirectBroker: attribute('redirect_uri', 'The HTTPS callback where Realm A receives Realm B’s authorization response.', 'Derived from Realm A’s broker configuration and registered on the broker client in B.', 'Returns the browser to A after authentication in B.', EXAMPLE.brokerCallback, 'RFC 6749 §4.1.1 / Keycloak brokering', URLS.keycloak),
  responseType: attribute('response_type', 'Chooses an authorization code response.', 'Set to code by each OIDC client.', 'Keeps tokens out of these browser redirects.', 'code', 'OIDC Core §3.1.2.1', URLS.oidc),
  scope: attribute('scope', 'A space-separated list of requested permissions and identity features.', 'Chosen by the requesting client and constrained by the realm’s configuration.', 'openid selects OIDC; other scopes affect claims and permissions.', 'openid profile', 'OIDC Core §3.1.2.1', URLS.oidc),
  stateApp: attribute('state', 'A random label for the app’s own sign-in attempt.', 'Generated by the native app and retained locally.', 'The app compares the returned value before accepting its callback.', EXAMPLE.stateApp, 'RFC 6749 §4.1.1 and §10.12', URLS.oauth),
  stateBroker: attribute('state', 'A separate correlation value for the broker’s sign-in attempt in B.', 'Generated by Realm A for the A-to-B request.', 'Lets A match B’s callback to the correct broker session.', EXAMPLE.stateBroker, 'RFC 6749 §4.1.1 and §10.12', URLS.oauth),
  nonceApp: attribute('nonce', 'A random value the app expects inside A’s ID token.', 'Generated by the app for this OIDC request.', 'Binds the received identity token to this sign-in attempt.', EXAMPLE.nonceApp, 'OIDC Core §3.1.2.1 and §3.1.3.7', URLS.oidc),
  nonceBroker: attribute('nonce', 'A different nonce that A expects inside B’s ID token.', 'Generated by A; this example explicitly includes it on the broker hop.', 'Binds B’s identity token to A’s authentication request.', EXAMPLE.nonceBroker, 'OIDC Core §3.1.2.1 and §3.1.3.7', URLS.oidc),
  codeVerifier: attribute('code_verifier', 'A high-entropy one-time secret for the app’s authorization code exchange.', 'Generated and retained by the app before opening the browser.', 'Proves that the app redeeming the code began the PKCE request.', EXAMPLE.verifier, 'RFC 7636 §4.1', URLS.pkce),
  codeChallenge: attribute('code_challenge', 'The public PKCE commitment derived from code_verifier.', 'The app computes BASE64URL(SHA256(ASCII(code_verifier))), without padding.', 'A remembers it and checks the verifier during the token exchange.', EXAMPLE.challenge, 'RFC 7636 §4.2', URLS.pkce),
  codeChallengeMethod: attribute('code_challenge_method', 'The method used to derive the PKCE challenge.', 'Selected by the app.', 'S256 tells A to compare the SHA-256-based commitment.', 'S256', 'RFC 7636 §4.2', URLS.pkce),
  grantType: attribute('grant_type', 'Names the operation requested at the token endpoint.', 'Set by the client redeeming an authorization code.', 'Selects authorization-code exchange instead of another grant.', 'authorization_code', 'RFC 6749 §4.1.3', URLS.oauth),
  codeA: attribute('code', 'A short-lived, single-use authorization code issued by Realm A.', 'Generated by A after the brokered sign-in succeeds.', 'The app exchanges it at A’s token endpoint with its PKCE verifier.', EXAMPLE.codeA, 'RFC 6749 §4.1.2', URLS.oauth),
  codeB: attribute('code', 'A different short-lived, single-use code issued by Realm B.', 'Generated by B after its configured authentication factors succeed.', 'Only the registered broker redeems it at B’s token endpoint.', EXAMPLE.codeB, 'RFC 6749 §4.1.2', URLS.oauth),
