  accessTokenA: attribute('access_token', 'An authorization token issued by A for permitted resources.', 'Realm A issues it according to client scopes and audience configuration.', 'The app presents it to an appropriate API; it is not a replacement for ID-token validation.', 'A-issued access token; API audience depends on configuration', 'RFC 6749 §1.4', URLS.oauth),
