  refreshToken: attribute('refresh_token', 'An optional credential for obtaining another access token.', 'Issued by A if the client and realm policies allow it.', 'Lets the app request fresh tokens without repeating the full browser sign-in.', 'optional, according to Realm A policy', 'RFC 6749 §1.5', URLS.oauth),
