  audience: attribute('aud', 'The intended recipient or recipients of a token.', 'Chosen by the issuer for the token’s type and client configuration.', 'An ID token must include the receiving OIDC client’s client_id; an API access token has its own audience rules.', 'ID token A: desktop-app; ID token B: realm-a-broker', 'OIDC Core §2 / RFC 7519 §4.1.3', URLS.jwt),
  subjectA: attribute('sub', 'The subject identifier of this user within A.', 'Assigned by Realm A to its local linked or imported user.', 'Identifies the app’s user together with A’s iss; it need not equal B’s sub.', 'user-in-A-204', 'OIDC Core §2', URLS.oidc),
  subjectB: attribute('sub', 'The subject identifier of this user within B.', 'Assigned by Realm B.', 'A uses the trusted external identity and broker mapping policy to resolve its local user.', 'user-in-B-913', 'OIDC Core §2', URLS.oidc),
  exp: attribute('exp', 'The time after which the token must not be accepted.', 'Set by the issuer as a NumericDate, measured in seconds since the Unix epoch.', 'Limits how long a token is valid.', 'iat + 300 (illustrative)', 'RFC 7519 §4.1.4', URLS.jwt),
  iat: attribute('iat', 'The time when the token was issued.', 'Set by the issuer as a NumericDate.', 'Helps clients assess the token’s issuance time under their validation policy.', 'Unix-epoch seconds', 'RFC 7519 §4.1.6', URLS.jwt),
  jwksUri: attribute('jwks_uri', 'The discovery address of a realm’s public token-verification keys.', 'Published in OIDC provider metadata.', 'Lets a client retrieve public keys to validate realm-signed tokens.', 'https://idp1.example.test/realms/realm-a/protocol/openid-connect/certs', 'OIDC Discovery §3', URLS.discovery),
  authorizationEndpoint: attribute('authorization_endpoint', 'The metadata address that begins browser-based authorization.', 'Published in the realm’s OIDC discovery document.', 'The client sends the browser here with its authorization request.', 'A or B: /protocol/openid-connect/auth', 'OIDC Discovery §3', URLS.discovery),
  tokenEndpoint: attribute('token_endpoint', 'The metadata address for direct code-to-token exchange.', 'Published in the realm’s discovery document.', 'The native app or broker calls it directly over HTTPS.', 'A or B: /protocol/openid-connect/token', 'OIDC Discovery §3', URLS.discovery),
  realmSigningKey: attribute('realm signing key (private)', 'The realm’s private key used to sign tokens; this is not a request parameter.', 'Provisioned and retained by the Keycloak realm’s key provider.', 'Lets receivers validate realm-issued JWTs with the matching published public key.', 'Separate signing keys for A and B', 'Keycloak realm keys / OIDC Core §2', URLS.keycloak),
  session: attribute('authentication session / SSO session', 'Keycloak’s server-side sign-in context; its cookie details are implementation-specific.', 'Created and managed by the relevant realm.', 'Connects browser actions and can enable later single sign-on.', 'A session and B session are separate', 'Keycloak sessions', URLS.keycloak),
