  rpName: attribute('rp.name', 'The readable name of the relying party during registration.', 'Configured by B.', 'Helps the user recognize the service creating a passkey.', 'Keycloak Realm B', 'WebAuthn §5.4.2', URLS.webauthn),
  origin: attribute('origin', 'The security origin of the page invoking WebAuthn.', 'The browser derives it from B’s loaded HTTPS page.', 'B checks it to prevent another website from impersonating its sign-in page.', EXAMPLE.origin, 'WebAuthn §5.8.1 / §7.2', URLS.webauthn),
