  userVerification: attribute('userVerification', 'The policy requiring a local check of the user.', 'Configured in B’s WebAuthn policy and requested in the ceremony.', 'required asks for PIN, biometrics or another supported local verification mechanism.', 'required', 'WebAuthn §5.4.6 / §5.5', URLS.webauthn),
  timeout: attribute('timeout', 'A browser waiting-time hint for the WebAuthn operation, in milliseconds.', 'Chosen by the relying party.', 'Controls the interaction window; it is not an authorization-code or token lifetime.', '60000', 'WebAuthn §5.4 / §5.5', URLS.webauthn),
