  attestation: attribute('attestation', 'The registration request’s preference for device-provenance evidence conveyed to the relying party.', 'Chosen by the relying party’s enrollment policy.', 'none requests that identifying attestation evidence is not conveyed to the relying party; the browser may replace the authenticator’s attestation statement with none.', 'none', 'WebAuthn §5.4.7', URLS.webauthn),
