const payload = (name, value, description) => ({ name, value, ...(description ? { description } : {}) });
const tokenClaim = (name, value) => payload(name, value, 'A claim inside the decoded id_token, not a separate top-level token endpoint response field.');
const step = (id, title, from, to, phase, channel, summary, detail, fields, data, checks = []) => ({
  id, title, from, to, phase, channel, summary, detail, fields, payload: data, checks,
});

