export const LEARNING_NOTES = [
  { title: 'Two OIDC hops, one passkey ceremony', text: 'App ↔ A and broker A ↔ B have different clients, callbacks, states, nonces, codes and tokens. The passkey ceremony takes place only on B’s login page.' },
  { title: 'One authenticator per attempt', text: 'Select YubiKey or Windows Hello. They are alternative ways to produce the same kind of WebAuthn proof.' },
  { title: 'Four different protections', text: 'state matches callbacks; nonce binds ID tokens; PKCE binds code redemption to the app; the WebAuthn challenge makes the passkey proof fresh.' },
  { title: 'The browser calls localhost', text: 'A redirects the browser to the loopback address. The browser calls the local listener; the Keycloak server does not connect to your computer.' },
  { title: 'Passkey keys and realm keys differ', text: 'The authenticator signs WebAuthn proof with the credential private key. B and A sign their own OIDC tokens with separate realm signing keys.' },
  { title: 'Same hostname does not merge realms', text: 'If A and B use one hostname, their WebAuthn RP scope may be the same because URL paths do not define RP IDs. B’s registered credential/public-key account binding is still not automatically registered in A.' },
  { title: 'Sessions can shorten real sign-in', text: 'An existing A or B SSO session can skip parts of this fresh-login demonstration. Enabling passkeys does not itself force every login to use them.' },
  { title: 'A token is not automatic passkey evidence', text: 'If an application needs proof of a fresh passkey login, enforce and validate an agreed authentication policy. acr and amr require explicit semantics and broker handling.' },
  { title: 'Canonical names, symbolic values', text: 'Protocol/API names follow IETF, OpenID and W3C specifications. Values in this simulator are illustrative; fields labelled Local operation or Stored in B describe actions, not wire parameters.' },
];

// MFA teaching extension. A TOTP app is a separate symmetric-key actor, not a
// WebAuthn authenticator. Password and OTP form fields below are application
// fields in Keycloak's login action, not RFC-defined OAuth request parameters.
const TOTP_RFC = 'https://www.rfc-editor.org/rfc/rfc6238';
const HOTP_RFC = 'https://www.rfc-editor.org/rfc/rfc4226';
const KEY_URI = 'https://github.com/google/google-authenticator/wiki/Key-Uri-Format';
const OTP_FORM = 'https://github.com/keycloak/keycloak/blob/main/themes/src/main/resources/theme/base/login/login-otp.ftl';
const DEMO_SEED = 'GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ'; // RFC's public test key; not a real secret.
const DEMO_OTP = '287082'; // RFC 6238 SHA1 vector at Unix time 59, reduced to six digits.
const DEMO_URI = 'otpauth://totp/Realm%20B:alice?secret=' + DEMO_SEED + '&issuer=Realm%20B&algorithm=SHA1&digits=6&period=30';

Object.assign(ATTRIBUTES, {
  password: attribute('password (login form field)', 'The account password submitted to B’s login action.', 'Chosen by the person or provisioned through the account’s password setup.', 'Provides the knowledge factor in this password-plus-TOTP example. It is not a client_secret or an OAuth password grant.', 'Password submitted to B over HTTPS; value hidden', 'Keycloak browser authentication (not an OAuth parameter)', URLS.keycloak),
  passwordHash: attribute('password hash (stored credential)', 'B’s protected password-verification record, with algorithm and salt metadata.', 'Created by B’s configured password hashing provider during account password setup.', 'Lets B verify the submitted password without storing it as plaintext. This record is not sent to the browser.', 'Salted password hash; provider and cost are configuration-dependent', 'Keycloak password policies and providers', URLS.keycloak),
  otpCode: attribute('otp (TOTP login form field)', 'The short numeric code the person types into B’s OTP form.', 'The TOTP app computes it locally from shared secret K and the current time-step counter.', 'B recomputes candidate codes to check possession of the enrolled TOTP secret. The form name is implementation-specific, not an OAuth/OIDC parameter.', DEMO_OTP + ' (public RFC test example at Unix time 59)', 'RFC 6238 algorithm / Keycloak OTP form', TOTP_RFC),
  otpSecret: attribute('K / secret', 'The per-credential symmetric secret shared by B and the TOTP app.', 'B generates a random secret during this enrollment example and provisions it once to the app.', 'Both parties need the same secret to calculate matching codes. Unlike a passkey private key, this secret is held by the server too.', DEMO_SEED + ' (public RFC test seed only)', 'RFC 6238 §3 / RFC 4226 §5.1', TOTP_RFC),
  otpAlgorithm: attribute('algorithm (provisioning setting)', 'The HMAC hash algorithm used to calculate the OTP.', 'B selects it in the OTP policy and provisions the same choice to the app.', 'Keeps the client and server’s code calculations consistent.', 'SHA1 in this example; RFC 6238 also specifies SHA256 and SHA512 variants', 'RFC 6238 / de facto otpauth URI', TOTP_RFC),
  otpDigits: attribute('Digit / digits', 'The number of decimal digits in the displayed OTP.', 'B’s OTP policy and the authenticator app agree during enrollment.', 'Both sides truncate and format the code to the same length, including leading zeros.', '6 in this example', 'RFC 4226 §5.3 / de facto otpauth URI', HOTP_RFC),
  otpPeriod: attribute('X / period', 'The length of one time step, in seconds.', 'Set by B’s OTP policy and provisioned to the app.', 'Determines when the time-step counter, and therefore the displayed code, changes.', '30 seconds', 'RFC 6238 §4.1 / de facto otpauth URI', TOTP_RFC),
  otpT0: attribute('T0', 'The starting Unix time used to count TOTP time steps.', 'Agreed as a TOTP system parameter; commonly zero.', 'Provides the same time origin for the app and server.', '0 (Unix epoch)', 'RFC 6238 §4.1', TOTP_RFC),
  otpTime: attribute('Current Unix time', 'The current time in seconds since the Unix epoch.', 'Read independently from the authenticator device’s clock and B’s server clock.', 'Each side derives a time-step counter; clock drift may require a small configured acceptance window.', '59 seconds in the fixed RFC example', 'RFC 6238 §3 / §4.2', TOTP_RFC),
  otpCounter: attribute('T (time-step counter)', 'The integer time-based moving factor for the HOTP calculation.', 'Each side computes floor((Current Unix time − T0) / X).', 'TOTP = HOTP(K, T), using the shared K and this moving factor. It is not a WebAuthn challenge.', 'floor((59 − 0) / 30) = 1', 'RFC 6238 §4.2', TOTP_RFC),
  otpUri: attribute('otpauth URI (de facto provisioning format)', 'An enrollment URI carrying the secret, label and matching OTP settings.', 'B formats a provisioning URI and renders it as a QR code.', 'The authenticator app scans the QR code to configure the shared secret. This URI format is not defined by RFC 6238.', DEMO_URI, 'Google Authenticator Key URI Format; de facto convention', KEY_URI),
  otpWindow: attribute('TOTP validation window (policy)', 'The limited set of nearby time steps that B may check.', 'Configured by the realm’s OTP policy, with clocks and permitted drift in mind.', 'Allows small clock/timing differences while limiting how long a stolen code may be useful. A 30-second display period is not necessarily a 30-second acceptance window.', 'Keycloak default look-around 1: previous/current/next 30s steps; configurable', 'RFC 6238 §5.2 / §6 and Keycloak OTP policy', TOTP_RFC),
  otpReplay: attribute('Accepted time-step / replay state (server policy)', 'Server state recording which OTP time step has already succeeded.', 'Updated by the verifier after successful validation; implementation details vary.', 'A one-time verifier rejects a second successful use of the same OTP. In current Keycloak, Reusable code is disabled by default; enabling it changes this protection.', 'Reusable code disabled; previously successful time-step rejected', 'RFC 6238 §5.2 and Keycloak OTP policy', TOTP_RFC),
});

ACTORS.totp = {
  id: 'totp', name: 'Authenticator app', role: 'TOTP prover / possession factor',
  plainRole: 'Stores a shared secret and shows a changing numeric code.', color: '#2dd4bf',
  attributes: [attr('otpSecret', 'received'), attr('otpAlgorithm', 'static'), attr('otpDigits', 'static'), attr('otpPeriod', 'static'), attr('otpT0', 'static'), attr('otpTime', 'generated'), attr('otpCounter', 'generated'), attr('otpCode', 'generated'), attr('otpUri', 'received')],
  notes: ['Creates TOTP codes offline from the shared secret and local time.', 'The secret exists both in this app and in B’s verifier.', 'The code can be copied or phished; it is not cryptographically bound to B’s website origin.'],
};
ACTORS.user.attributes.push(attr('password', 'static'), attr('otpCode', 'received'));
ACTORS.browser.attributes.push(attr('password', 'received'), attr('otpCode', 'received'), attr('otpUri', 'received'));
ACTORS.realmB.attributes.push(attr('passwordHash', 'static'), attr('password', 'received'), attr('otpSecret', 'generated'), attr('otpAlgorithm', 'static'), attr('otpPeriod', 'static'), attr('otpDigits', 'static'), attr('otpCounter', 'generated'), attr('otpCode', 'received'), attr('otpWindow', 'static'), attr('otpReplay', 'generated'));
ACTORS.realmB.attributes.push(attr('rpObject', 'generated'), attr('userObject', 'generated'), attr('authenticatorSelection', 'static'));
ACTORS.browser.attributes.push(attr('rpObject', 'received'), attr('userObject', 'received'), attr('authenticatorSelection', 'received'));

const otpSteps = [
  step('m01', 'Request the second factor', 'realmB', 'browser', 'mfa', 'https',
    'B asks for a current code from the enrolled TOTP app.',
    'B keeps the sign-in pending until its required OTP execution succeeds. This OTP form belongs to B’s current browser authentication session, before B creates the broker authorization code. Requiring TOTP after a passkey needs an explicitly configured B flow; it is not implied by enabling passkeys.',
    ['session', 'otpCode', 'otpWindow'], [payload('HTTPS response', 'Realm B OTP input form'), payload('Required input', 'Current TOTP code')]),
  step('m02', 'Calculate and display a TOTP code', 'totp', 'user', 'mfa', 'local',
    'The authenticator app shows a code computed from its secret and clock.',
    'The app needs no live call to Keycloak. It computes T = floor((Current Unix time − T0) / X), then TOTP = HOTP(K, T) using the agreed HMAC algorithm, truncation and digit count. The fixed teaching example uses the public RFC test key, SHA1, six digits and Unix time 59; it is not a usable enrollment secret.',
    ['otpSecret', 'otpTime', 'otpT0', 'otpPeriod', 'otpCounter', 'otpAlgorithm', 'otpDigits', 'otpCode'],
    [payload('TOTP', DEMO_OTP + ' (fixed public test example)')]),
  step('m03', 'Type the code into B’s page', 'user', 'browser', 'mfa', 'local',
    'The person copies the displayed six-digit code into the login form.',
    'This is a human-mediated code transfer. Unlike WebAuthn, the typed TOTP code has no signed origin or RP ID binding. The same code can be relayed by a phishing site during its acceptance window.',
    ['otpCode'], [payload('otp', DEMO_OTP, 'Keycloak login-form field, not an OAuth parameter.')]),
  step('m04', 'Submit the OTP to Realm B', 'browser', 'realmB', 'mfa', 'https',
    'The browser posts the OTP to B over HTTPS.',
    'The code is bound to the current pending login action by B’s authentication session. The TOTP secret is not sent again on login, and this code is not sent to A or the native application.',
    ['otpCode', 'session'], [payload('HTTP', 'POST current Realm B login action'), payload('otp', DEMO_OTP)]),
  step('m05', 'Validate the time-based second factor', 'realmB', 'realmB', 'mfa', 'internal',
    'B checks the code against its stored secret and allowed time steps.',
    'B derives candidates from the same K, HMAC algorithm, time step and digits, applies its limited clock-drift window, and enforces configured attempt protection and one-time-use policy. Only after the required factors succeed does B proceed to the normal OIDC code response.',
    ['otpSecret', 'otpAlgorithm', 'otpDigits', 'otpPeriod', 'otpT0', 'otpCounter', 'otpWindow', 'otpReplay', 'otpCode'],
    [payload('Expected code', 'HOTP(K, T) for permitted time steps'), payload('Submitted otp', DEMO_OTP), payload('Outcome', 'Required B factors satisfied')],
    ['Enrolled OTP credential belongs to this B account', 'Code matches a permitted time step', 'Attempt-limit policy satisfied', 'Previously successful OTP rejected by replay policy']),
];

const passwordSteps = [
  step('p01', 'Show the password form', 'realmB', 'browser', 'password', 'https',
    'B asks the person for the account password.',
    'This alternative uses a browser password form followed by TOTP in Realm B. It still uses the authorization code flow between the app and A and between A and B; it does not use OAuth’s resource-owner password grant.',
    ['password', 'session'], [payload('HTTPS response', 'Realm B username/password form')]),
  step('p02', 'Enter account credentials', 'user', 'browser', 'password', 'local',
    'The person enters a username and password on B’s page.',
    'The knowledge factor is the B account password. The native app and Realm A do not receive that password in this brokered browser login.',
    ['userName', 'password'], [payload('username', 'alice', 'Keycloak form field; not an OAuth parameter.'), payload('password', '••••••••')]),
  step('p03', 'Submit the password to B', 'browser', 'realmB', 'password', 'https',
    'The browser sends the account credentials directly to B over HTTPS.',
    'B checks the username and password using the configured credential provider. A successful password check completes the knowledge factor but the sign-in stays pending until the required TOTP factor succeeds.',
    ['userName', 'password', 'passwordHash', 'session'],
    [payload('HTTP', 'POST current Realm B login action'), payload('username', 'alice'), payload('password', 'Hidden; TLS-protected request')],
    ['Account resolved in B', 'Password verified using B’s protected credential record']),
];

// Clone shared steps so mode-specific text never falsely describes passkeys.
// Key lookup and audience belong to this token occurrence, not the generic
// glossary example. Preserve both through factor/deployment/JWE adapters.
FLOWS.login.find(s => s.id === 'l18').attributeValues = {
  audience: EXAMPLE.clientBroker,
};
FLOWS.login.find(s => s.id === 'l19').attributeValues = {
  jwksUri: EXAMPLE.issuerB + '/protocol/openid-connect/certs',
  audience: EXAMPLE.clientBroker,
};
FLOWS.login.find(s => s.id === 'l24').attributeValues = {
  audience: EXAMPLE.clientApp,
};
FLOWS.login.find(s => s.id === 'l25').attributeValues = {
  jwksUri: EXAMPLE.issuerA + '/protocol/openid-connect/certs',
  audience: EXAMPLE.clientApp,
};

const rename = (s, prefix) => ({ ...s, id: prefix + '-' + s.id, fields: [...s.fields], payload: s.payload.map(p => ({ ...p })), checks: [...s.checks] });
const totpStart = FLOWS.login.slice(0, 7).map(s => rename(s, 'totp'));
totpStart[6].detail = 'B validates the broker registration and callback, then starts its configured browser flow. This mode uses the account password followed by an enrolled TOTP factor.';
const totpReturn = FLOWS.login.slice(14).map(s => rename(s, 'totp'));
totpReturn[3].summary = 'B sends an identity token for A’s broker client after the required factors succeed.';
totpReturn[3].detail = 'B validates the code and client and returns its realm-signed ID token plus an access token. The ID token has issuer B, audience realm-a-broker and the broker nonce. TOTP secrets and codes are not included as the broker identity result.';
totpReturn[9].detail = 'A signs its own ID token for desktop-app and issues its own access token. An optional refresh token depends on A’s policy. B’s ID token, password and OTP code are not forwarded as the app’s login result.';
totpReturn[10].detail = 'The app uses A’s trusted discovered public keys and validates signature, exact issuer, audience, expiry and its original nonce, with any additional required OIDC checks. Its accepted identity is (iss A, sub user-in-A-204). If it must enforce a specific MFA level, it needs an agreed authentication policy and validated claim semantics.';
FLOWS.totpLogin = [...totpStart, ...passwordSteps, ...otpSteps, ...totpReturn];
FLOWS.passkeyTotpLogin = [
  ...FLOWS.login.slice(0, 14).map(s => rename(s, 'passkey-mfa')),
  ...otpSteps.map(s => rename(s, 'passkey')),
  ...FLOWS.login.slice(14).map(s => rename(s, 'passkey-mfa')),
];
FLOWS.passkeyTotpLogin[13].summary = 'B validates the passkey step; required TOTP is still pending.';
FLOWS.passkeyTotpLogin[13].detail = 'B resolves the credential/account, verifies type, current challenge, permitted origin and RP ID hash, requires UP and UV, and verifies the signature using its stored credentialPublicKey. It evaluates signCount and relevant credential metadata. This completes only the passkey step: B keeps authentication pending until its separately configured required TOTP execution succeeds.';
FLOWS.passkeyTotpLogin[14].summary = 'After validating the passkey, B still requires a separate TOTP factor.';
FLOWS.passkeyTotpLogin[14].detail = 'This mode illustrates a custom B browser authentication flow with a required OTP execution after passkey verification. It is not the default consequence of enabling passkeys; real deployments must configure and test the requirement and avoid session/fallback paths bypassing it.';

FLOWS.totpEnrollment = [
  step('t01', 'Begin from a verified B account', 'user', 'browser', 'enrollment', 'local',
    'The person chooses to add an authenticator app to a verified B account.',
    'TOTP setup is a separate enrollment ceremony. B must already know and verify the account identity before binding a new possession factor. The QR image carries a secret, so real setup pages must protect it.',
    ['session', 'otpSecret'], [payload('Local action', 'Configure OTP for verified B account')]),
  step('t02', 'Authorize TOTP setup', 'browser', 'realmB', 'enrollment', 'https',
    'The browser requests setup in the verified B session.',
    'B checks authorization for adding this credential and selects OTP settings from the realm’s OTP policy. Keycloak can initiate this using the Configure OTP required action.',
    ['session', 'otpAlgorithm', 'otpDigits', 'otpPeriod'], [payload('HTTPS action', 'Configure OTP for verified user-in-B-913')], ['Verified account and session', 'Credential enrollment authorized']),
  step('t03', 'Generate the shared secret and QR', 'realmB', 'browser', 'enrollment', 'https',
    'B creates a new per-credential secret and shows the provisioning QR.',
    'B generates a high-entropy secret K and creates a de facto otpauth URI with matching algorithm, digits and period. The QR contains this secret; it is not a public-key registration response. The shown seed is a publicly documented RFC test seed for illustration only.',
    ['otpSecret', 'otpUri', 'otpAlgorithm', 'otpDigits', 'otpPeriod', 'otpT0'],
    [payload('Provisioning URI (de facto)', DEMO_URI), payload('secret', DEMO_SEED + ' (public test seed only)'), payload('algorithm', 'SHA1'), payload('digits', '6'), payload('period', '30')]),
  step('t04', 'Scan the provisioning QR', 'browser', 'totp', 'enrollment', 'local',
    'The authenticator app scans the QR shown on the browser’s setup page.',
    'The person initiates the scan. The app decodes the secret and settings, stores them securely and can now generate codes offline. This is an intentional one-time transfer of a shared symmetric secret, unlike passkey enrollment where the private key never goes to the server.',
    ['otpUri', 'otpSecret', 'otpAlgorithm', 'otpDigits', 'otpPeriod'],
    [payload('Optical/local provisioning', 'QR encodes otpauth URI'), payload('Provisioned settings', 'Secret K + algorithm + digits + period')]),
  step('t05', 'Generate a confirmation code', 'totp', 'user', 'enrollment', 'local',
    'The app shows its first time-based code for this enrollment.',
    'The app calculates TOTP from the newly provisioned secret and its local clock. The person will submit a current code so B can confirm that the app and server agree on the secret and settings.',
    ['otpSecret', 'otpTime', 'otpCounter', 'otpCode'], [payload('TOTP', DEMO_OTP + ' (fixed RFC example at Unix time 59)')]),
  step('t06', 'Enter the confirmation code', 'user', 'browser', 'enrollment', 'local',
    'The person types the displayed code into B’s setup form.',
    'This confirms possession of the configured app. The field label below describes the enrollment code; the exact Keycloak setup form field name is implementation-specific.',
    ['otpCode'], [payload('Enrollment OTP input (form-specific)', DEMO_OTP)]),
  step('t07', 'Validate and activate the credential', 'browser', 'realmB', 'enrollment', 'https',
    'B checks the confirmation code before binding this TOTP credential.',
    'B validates the current code against the pending secret and settings, checks the authorized setup session, and persists the account’s OTP credential according to its enrollment policy. B retains the symmetric secret, not just a public verification key.',
    ['otpCode', 'otpSecret', 'otpWindow', 'otpReplay', 'session'],
    [payload('HTTPS action', 'Submit setup confirmation'), payload('OTP input', DEMO_OTP)],
    ['Setup still authorized', 'Code and current time window match', 'TOTP credential bound to the verified account']),
  step('t08', 'Confirm TOTP enrollment', 'realmB', 'browser', 'enrollment', 'https',
    'B confirms that the account can now use the TOTP app.',
    'The shared secret is held both by B’s verifier and the enrolled app. Later login submits only the short OTP code. Realm A and the native application do not receive the TOTP seed or the typed OTP through ordinary brokering.',
    ['otpSecret', 'otpAlgorithm', 'otpDigits', 'otpPeriod'],
    [payload('HTTPS result', 'Authenticator app registered')]),
];

SOURCES.push(
  { name: 'Time-based one-time passwords', standard: 'RFC 6238', url: TOTP_RFC, note: 'Shared-secret TOTP calculation, time windows and one-time-use requirement.' },
  { name: 'HMAC-based one-time passwords', standard: 'RFC 4226', url: HOTP_RFC, note: 'HOTP calculation, dynamic truncation and decimal code formatting.' },
  { name: 'Authenticator provisioning URI', standard: 'De facto convention; not an RFC wire format', url: KEY_URI, note: 'otpauth URI and QR enrollment parameters.' },
  { name: 'Keycloak OTP login form', standard: 'Implementation-specific form', url: OTP_FORM, note: 'The OTP input is a browser login form field, not an OAuth/OIDC parameter.' },
);
LEARNING_NOTES.push(
  { title: 'MFA happens where the factors are checked', text: 'In these modes, B verifies the password/passkey and TOTP. A trusts the OIDC result and issues app tokens. Requiring a factor at A would be another explicitly configured authentication step.' },
  { title: 'Passkey plus TOTP is an explicit flow', text: 'The simulator can require TOTP after passkey verification. Keycloak needs a custom flow and consistent session/fallback policy to enforce that requirement.' },
  { title: 'TOTP shares a secret; passkeys use asymmetric keys', text: 'B and the TOTP app both store secret K. With a passkey, B stores the public key and the authenticator protects the private key.' },
  { title: 'TOTP codes can be phished', text: 'A typed code is not signed for a particular website origin. Use narrow time windows, attempt limits and replay protection; origin binding is a distinct advantage of correctly configured WebAuthn.' },
);
